  "revised_milestones": {
    "milestones": [
      {
        "task": "find red_wall_banner",
        "milestone_id": "find_red_wall_banner",
        "description": "Uses position_near_with_facing because this is a find/locate/observe task. The player must navigate through the oak plank occluder doorway and approach the red wall banner at spawn-relative (8, 2, 7) on the south face of the stone brick wall. max_distance=5 ensures the agent must actually walk ~8 blocks from spawn to get within range (the banner is ~10.6 blocks from spawn origin, so the agent cannot satisfy this at spawn). facing_tolerance=45 ensures the agent is deliberately looking at the banner, not just passing nearby.",
        "rules": [
          {
            "type": "position_near_with_facing",
            "params": {
              "target": [8, 2, 7],
              "max_distance": 5,
              "facing_tolerance": 45,
